import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { finalize, map } from 'rxjs/operators';
import {
  Denuncia,
  DenunciaFilters,
  PaginatedResponse
} from '../../../interfaces/denuncia.interface';
import { DenunciaService } from '../../../services/denuncia.service';
import { PersonaService } from '../../../services/persona.service';
import { switchMap, catchError } from 'rxjs/operators';
import { of, forkJoin } from 'rxjs';

export interface DenunciasState {
  items: Denuncia[];
  total: number;
  page: number;
  perPage: number;
  filters: DenunciaFilters;
  loading: boolean;
  selected: Denuncia | null;
}

@Injectable({
  providedIn: 'root'
})
export class DenunciasFacadeService {
  private readonly initialState: DenunciasState = {
    items: [],
    total: 0,
    page: 1,
    perPage: 10,
    filters: {
      codigo_externo: '',
      numero_expediente: '',
      estado_denuncia_id: undefined,
      tipo_conflicto_id: undefined,
      persona_id: undefined,
      fecha_inicio: '',
      fecha_fin: '',
      search: '',
      page: 1,
      per_page: 10
    },
    loading: false,
    selected: null
  };

  private stateSubject = new BehaviorSubject<DenunciasState>(this.initialState);
  readonly state$ = this.stateSubject.asObservable();

  readonly denuncias$: Observable<Denuncia[]> = this.state$.pipe(
    map(state => state.items)
  );

  readonly loading$: Observable<boolean> = this.state$.pipe(
    map(state => state.loading)
  );

  readonly pagination$ = this.state$.pipe(
    map(state => ({
      page: state.page,
      perPage: state.perPage,
      total: state.total
    }))
  );

  readonly selectedDenuncia$ = this.state$.pipe(
    map(state => state.selected)
  );

  constructor(private readonly denunciaService: DenunciaService, private readonly personaService: PersonaService) {}

  init(): void {
    this.loadDenuncias();
  }

  setPage(page: number): void {
    const current = this.stateSubject.value;
    this.patchState({
      page,
      filters: { ...current.filters, page }
    });
    this.loadDenuncias();
  }

  setPerPage(perPage: number): void {
    const current = this.stateSubject.value;
    this.patchState({
      perPage,
      page: 1,
      filters: { ...current.filters, page: 1, per_page: perPage }
    });
    this.loadDenuncias();
  }

  updateFilters(partial: Partial<DenunciaFilters>): void {
    const current = this.stateSubject.value;
    const filters: DenunciaFilters = {
      ...current.filters,
      ...partial,
      page: 1
    };
    this.patchState({ filters, page: 1 });
    this.loadDenuncias();
  }

  clearFilters(): void {
    this.patchState({
      filters: { ...this.initialState.filters },
      page: 1
    });
    this.loadDenuncias();
  }

  selectDenuncia(denuncia: Denuncia | null): void {
    this.patchState({ selected: denuncia });
  }

  reloadCurrentPage(): void {
    this.loadDenuncias();
  }

private loadDenuncias(): void {
const current = this.stateSubject.value;
this.patchState({ loading: true });

this.denunciaService
.getDenuncias({
...current.filters,
page: current.page,
per_page: current.perPage
})
.pipe(
finalize(() => this.patchState({ loading: false })),
switchMap((response: any) => {
const data: Denuncia[] = (response as any).data ?? [];
const pagination = (response as any).pagination ?? {};
    const idsToLoad = Array.from(new Set(
      data
        .filter(d => !d.persona && d.persona_id != null)
        .map(d => d.persona_id as number)
    ));

    if (idsToLoad.length === 0) {
      return of({ items: data, total: pagination.total ?? data.length });
    }

    const calls = idsToLoad.map(id =>
      this.personaService.obtenerPersona(id).pipe(
        map((r: any) => ({ id, persona: r?.data ?? null })),
        catchError(() => of({ id, persona: null }))
      )
    );

    return forkJoin(calls).pipe(
      map(results => {
        const byId: Record<number, any> = {};
        results.forEach((r: any) => { if (r && r.id != null) byId[r.id] = r.persona; });

        const enriched = data.map(d => ({
          ...d,
          persona: d.persona ?? (d.persona_id != null ? (byId[d.persona_id] ?? null) : null)
        }));

        return { items: enriched, total: pagination.total ?? enriched.length };
      })
    );
  })
)
.subscribe({
  next: (res: any) => {
    this.patchState({
      items: res.items,
      total: res.total
    });
  },
  error: () => {
    this.patchState({
      items: [],
      total: 0
    });
  }
});
}

  private patchState(partial: Partial<DenunciasState>): void {
    this.stateSubject.next({
      ...this.stateSubject.value,
      ...partial
    });
  }
}
