private cargarCatalogos(): void {
  this.loadingCatalogs = true;

  // Cargar en paralelo
  forkJoin({
    tiposConflicto: this.catalogoService.getTiposConflicto().pipe(catchError(() => of([]))),
    estadosDenuncia: this.catalogoService.getEstadosDenuncia().pipe(catchError(() => of([])))
  }).pipe(
    takeUntil(this.destroy$)
  ).subscribe({
    next: (result) => {
      console.log('📊 Catálogos cargados:', result);
      this.tiposConflicto = result.tiposConflicto;
      this.estadosDenuncia = result.estadosDenuncia;
      this.loadingCatalogs = false;
      this.cdr.detectChanges();
    },
    error: (error) => {
      console.error('❌ Error cargando catálogos:', error);
      this.loadingCatalogs = false;
      this.cdr.detectChanges();
    }
  });
}


